"""Write paper/results/hcrl_SUMMARY.md from the JSON results (every number is read from results, none typed by hand).

    python -m paper.experiments.hcrl_summary
"""
from __future__ import annotations

from paper.experiments import hcrl_common as H
from paper.experiments import style


def main():
    D, R, F, T, S, W = (H.load_json(n) for n in ("hcrl_dataset", "hcrl_rules", "hcrl_rf", "hcrl_transfer",
                                                    "hcrl_sensitivity", "hcrl_window"))
    files = D["files"]
    fl = lambda n: files[n]  # noqa: E731
    ra, rs = R["all"], R["settled"]
    pi = R["per_intrusion"]
    L = []
    A = L.append

    def lat(n):
        x = pi[n]["latency_ms"]
        return f"{x['median']:.0f} / {x['p95']:.0f} / {x['max']:.0f} ms"

    mm = T["macro_f1"]
    g = lambda k, t, m: mm[k][t][m]["mean"]  # noqa: E731
    sd = lambda k, t, m: mm[k][t][m]["sd"]  # noqa: E731
    nom_pc = T["hcrl_heldout_per_class_seed0"]["synth_nominal"]["all"]
    fm = T["feature_medians"]
    fig = lambda n: f"paper/figures/{n}.pdf (+ .png)"  # noqa: E731

    A("# HCRL real-data results: summary for the Results section\n")
    A("All numbers below are produced by the scripts in `paper/experiments/hcrl_*.py` (run `python -m paper.experiments.run_hcrl_all` from the project root; "
      "this file is generated by `hcrl_summary.py` from `paper/results/hcrl_*.json`). Data: HCRL Car-Hacking (Seo et al. 2018), one Hyundai YF Sonata, "
      "DoS / fuzzy / RPM-spoof / gear-spoof captures with 300 intrusions each plus 506 s of attack-free driving. "
      "Windows are 100 ms batches unless stated; a window is an attack window if it contains at least one injected frame. "
      "'Settled' = windows more than 0.7 s after a label change (the detector's 0.5 s rate smoothing lags the label); 'all' includes them and is the operational number.\n")
    A("## Headline numbers\n")
    A(f"- Rule engine (no ML): {R['detected_total']}/{R['intrusions_total']} real intrusions detected with the correct alert category; "
      f"median latency {min(pi[n]['latency_ms']['median'] for n in H.ATTACK_FILES):.0f} to {max(pi[n]['latency_ms']['median'] for n in H.ATTACK_FILES):.0f} ms across the four attacks; "
      f"{R['normal_run']['cyber_alerts']} cyber alerts in {R['normal_run']['duration_s']:.0f} s of normal driving and "
      f"{R['attack_capture_normal_stretches']['cyber_alerts_outside']} alerts in {R['attack_capture_normal_stretches']['seconds']:.0f} s of attack-free stretches.")
    A(f"- Window-level macro-F1 of the rules: {ra['macro_f1']:.3f} (all windows), {rs['macro_f1']:.3f} (settled).")
    A(f"- RandomForest on the time-contiguous HCRL hold-out: macro-F1 {F['models']['hcrl_only']['all']['macro_f1']:.3f} (all) / "
      f"{F['models']['hcrl_only']['settled']['macro_f1']:.3f} (settled). The deployed HCRL+simulator RF is indistinguishable on this hold-out "
      f"(macro-F1 {F['models']['deployed']['all']['macro_f1']:.3f} / {F['models']['deployed']['settled']['macro_f1']:.3f}).")
    A(f"- Cross-domain (key result): an RF trained only on the simulator WITHOUT measured attack behaviour reaches macro-F1 "
      f"{g('synth_nominal', 'hcrl_heldout', 'all'):.2f} (all) / {g('synth_nominal', 'hcrl_heldout', 'settled'):.2f} (settled) on real HCRL; with the attack behaviour "
      f"measured from HCRL put into the simulator it reaches {g('synth_measured', 'hcrl_heldout', 'all'):.2f} / {g('synth_measured', 'hcrl_heldout', 'settled'):.2f} "
      f"(mean over {len(T['seeds'])} simulator seeds, s.d. {sd('synth_nominal', 'hcrl_heldout', 'all'):.3f} and {sd('synth_measured', 'hcrl_heldout', 'all'):.3f}). "
      f"HCRL-trained RF: {g('hcrl', 'hcrl_heldout', 'all'):.2f} / {g('hcrl', 'hcrl_heldout', 'settled'):.2f}.")
    d = [q for q in S["DOS_UNKNOWN_ID_FPS"]["points"] if q["value"] == S["DOS_UNKNOWN_ID_FPS"]["default"]][0]
    A(f"- Thresholds: at the deployed values the false-positive rate on settled normal windows is 0 for all three sweeps; the DoS threshold is the sensitive one "
      f"(recall {100 * d['recall_any_settled']:.1f} % at {S['DOS_UNKNOWN_ID_FPS']['default']} frames/s, falling to "
      f"{100 * S['DOS_UNKNOWN_ID_FPS']['points'][-1]['recall_any_settled']:.1f} % at {S['DOS_UNKNOWN_ID_FPS']['points'][-1]['value']}).")
    wl = ", ".join("%.0f" % W[str(s)]["latency_median_ms"] for s in (50, 100, 200, 500))
    wd = ", ".join("%.1f" % (100 * W[str(s)]["detect_rate"]) for s in (50, 100, 200, 500))
    A(f"- Window size: 50/100/200/500 ms give median latency {wl} ms with {wd} % of intrusions detected.\n")

    # ------------------------------------------------------------------ Exp 1
    A("## Exp 1: dataset characterisation\n")
    A(f"### Table `paper/tables/hcrl_dataset_files.tex` (label `tab:hcrl_dataset`)\n")
    A("**Caption draft.** The four HCRL attack captures and the attack-free recording. Each attack capture holds 300 injection bursts; during a burst the injected frames "
      "crowd legitimate traffic off the bus, most strongly for DoS and fuzzy.\n")
    A("**Key numbers.** " + "; ".join(
        f"{H.FILE_SHORT[n]}: {fl(n)['duration_s']:.0f} s, {fl(n)['frames'] / 1e6:.2f} M frames, {fl(n)['distinct_ids']} IDs, {fl(n)['injected_frames']:,} injected, "
        f"{fl(n)['intrusions']} intrusions" + (f", target {fl(n)['attack_target']}, {fl(n)['median_inject_fps']:.0f} injected frames/s, "
                                                f"{100 * fl(n)['median_legit_retained']:.0f} % of legitimate traffic kept (burst median {fl(n)['median_duration_s']:.1f} s, "
                                                f"gap {fl(n)['median_gap_between_intrusions_s']:.1f} s)" if n != "normal_run_data.txt" else "")
        for n in H.ATTACK_FILES + ["normal_run_data.txt"]) + ".\n")
    A("**Method.** One streaming pass over every raw file (`ml_training.hcrl_import` parser); an intrusion is a run of injected (T) frames separated by less than 1.5 s. "
      "Durations exclude timestamp jumps greater than 5 s: the captures concatenate recording sessions, e.g. "
      + ", ".join(f"{H.FILE_SHORT[n]} {files[n]['span_s']:.0f} s span vs {files[n]['duration_s']:.0f} s active" for n in H.ATTACK_FILES if files[n]['timestamp_jumps'])
      + ". 'Legit. kept' = legitimate frames/s inside the burst / legitimate frames/s in the 0.9 s before it.\n")
    A("### Figure `" + fig("hcrl_id_rates") + "`\n")
    A(f"**Caption draft.** Frame rate of each CAN ID during normal driving (log scale). All {len(D['normal_per_id_hz'])} IDs are periodic, "
      f"the fastest at {D['fastest_legit_hz']:.0f} Hz; the total is {D['normal_total_hz']:.0f} frames/s. Blue: the {len(D['profile_messages_on_hcrl_bus'])} messages the profile decodes "
      "(rpm, speed, coolant, throttle, steering, gear); grey: background IDs checked for rate only.\n")
    A(f"**Key numbers.** Total {D['normal_total_hz']:.0f} frames/s over {len(D['normal_per_id_hz'])} IDs; rates between {min(D['normal_per_id_hz'].values()):.0f} and "
      f"{max(D['normal_per_id_hz'].values()):.0f} Hz. This is why a rate threshold of 100 frames/s on any single unknown ID separates DoS from normal traffic.\n")
    A("**Method.** Frame count per ID in `normal_run_data.txt` divided by its duration. Profile messages = those in `common/profiles/hyundai_sonata_hcrl.json` `messages`.\n")
    A("### Figure `" + fig("hcrl_burst_timeseries") + "`\n")
    rep = D["representative_intrusions"]
    A("**Caption draft.** One representative intrusion per attack (frames per second in 20 ms bins, legitimate vs injected). Shaded: injection burst. "
      "Injection suppresses legitimate traffic: strongly under DoS and fuzzing, mildly under spoofing, and the injected rate is far below the nominal 1 kHz.\n")
    A("**Key numbers.** " + "; ".join(
        f"{H.FILE_SHORT[n]}: legit {rep[n]['mean_legit_fps_before']:.0f} -> {rep[n]['mean_legit_fps_in_burst']:.0f} frames/s, burst {rep[n]['duration_s']:.1f} s, {rep[n]['injected_frames']:,} injected"
        for n in H.ATTACK_FILES) + ".\n")
    A(f"**Method.** {D['representative_rule']}. Frames binned at 20 ms from -1.5 s before to 1.5 s after the burst; deterministic choice, not cherry-picked.\n")

    # ------------------------------------------------------------------ Exp 2
    A("## Exp 2: rule-based detector on real traffic (VehicleAnalyzer, models=None)\n")
    A("### Table `paper/tables/hcrl_rules_perclass.tex` (`tab:hcrl_rules_perclass`)\n")
    A("**Caption draft.** Per-class precision, recall and F1 of the rule engine on real HCRL traffic, 100 ms windows, all captures pooled.\n")
    A("**Key numbers (all windows, P/R/F1).** " + "; ".join(
        f"{c}: {ra[c]['precision']:.3f}/{ra[c]['recall']:.3f}/{ra[c]['f1']:.3f} (N={ra[c]['support']})" for c in H.CLASSES)
      + ". **Settled:** " + "; ".join(f"{c}: {rs[c]['precision']:.3f}/{rs[c]['recall']:.3f}/{rs[c]['f1']:.3f}" for c in H.CLASSES)
      + f". Macro-F1 {ra['macro_f1']:.3f} (all) and {rs['macro_f1']:.3f} (settled). Almost all errors are boundary windows: {R['unsettled_windows']:,} of {R['windows']:,} windows are unsettled. "
        "The precision loss in 'all windows' comes from normal windows right after a burst still seeing smoothed attack rates (the rate smoothing is 0.5 s).\n")
    A("**Method.** `VehicleAnalyzer(profile, None)` is fed every 100 ms batch of all five captures in time order; the window class is the highest-priority rule category active in that window "
      "(DoS > fuzzy > spoofing). Reproduces `EVALUATION.md` exactly (anchor-checked against `tools/eval_hcrl.py`).\n")
    A("### Figure `" + fig("hcrl_rules_confusion") + "`\n")
    A("**Caption draft.** Row-normalised 4x4 window confusion matrices of the rule detector on real HCRL data (left: all windows, right: settled windows). "
      "Off-diagonal mass is concentrated at burst edges.\n")
    cmA, cmS = R["confusion_all"], R["confusion_settled"]
    A(f"**Key numbers.** All windows: normal->attack {100 * (1 - cmA[0][0] / sum(cmA[0])):.1f} %, DoS->normal {100 * cmA[1][0] / sum(cmA[1]):.1f} %, "
      f"fuzzy->normal {100 * cmA[2][0] / sum(cmA[2]):.1f} %, spoofing->normal {100 * cmA[3][0] / sum(cmA[3]):.1f} %; no confusion between attack classes. "
      f"Settled: normal->attack {100 * (1 - cmS[0][0] / sum(cmS[0])):.2f} %, DoS->normal {100 * cmS[1][0] / sum(cmS[1]):.2f} %, spoofing->normal {100 * cmS[3][0] / sum(cmS[3]):.2f} %.\n")
    A("**Method.** Same replay as above; sklearn confusion matrix, each row divided by its sum.\n")
    A("### Table `paper/tables/hcrl_rules_latency.tex` (`tab:hcrl_rules_latency`) and figure `" + fig("hcrl_rules_latency_ecdf") + "`\n")
    A("**Caption draft.** Per-intrusion detection and latency of the rule engine. Latency is the time from the first injected frame to the first alert of the matching category; "
      "ECDF over the 300 intrusions of each attack.\n")
    A("**Key numbers (median / p95 / max).** " + "; ".join(
        f"{H.FILE_SHORT[n]}: {pi[n]['detected']}/{pi[n]['intrusions']} detected (95 % Wilson CI {100 * pi[n]['wilson95'][0]:.1f}-{100 * pi[n]['wilson95'][1]:.1f} %), {lat(n)}, "
        f"{pi[n]['alerts_outside_intrusions']} alerts outside bursts, {pi[n]['wrong_class_alerts']} wrong-class alerts" for n in H.ATTACK_FILES)
      + f". Normal driving: {R['normal_run']['cyber_alerts']} cyber / {R['normal_run']['mechanical_alerts']} mechanical alerts in {R['normal_run']['duration_s']:.0f} s; "
        f"{R['attack_capture_normal_stretches']['cyber_alerts_outside']} alerts in {R['attack_capture_normal_stretches']['seconds']:.0f} s of attack-free stretches inside the attack captures. "
        "Latency cannot be below one 100 ms window by construction (the batch must arrive) and includes the rate-smoothing delay; the DoS tail is the longest because legitimate and injected traffic are both thinned. "
        "300 identical bursts are not 300 independent samples (see threats).\n")
    A("**Method.** An intrusion = a run of attack windows (gaps up to 0.3 s merged); detected if an alert of the matching category (dos / fuzzy / spoofing_rpm / spoofing_gear) is raised between its first injected frame "
      "and 1 s after its last window. Alerts are debounced (re-armed after 2 s quiet), so exactly one alert per burst.\n")

    # ------------------------------------------------------------------ Exp 3
    A("## Exp 3: RandomForest on HCRL\n")
    mo, md = F["models"]["hcrl_only"], F["models"]["deployed"]
    A("### Table `paper/tables/hcrl_rf_perclass.tex` (`tab:hcrl_rf_perclass`)\n")
    A("**Caption draft.** Per-class precision/recall/F1 of the RandomForest on the time-contiguous hold-out (last 25 % of every capture). HCRL-only versus the deployed HCRL+simulator model.\n")
    A("**Key numbers (HCRL-only, all windows P/R/F1).** " + "; ".join(
        f"{c}: {mo['all'][c]['precision']:.3f}/{mo['all'][c]['recall']:.3f}/{mo['all'][c]['f1']:.3f} (N={mo['all'][c]['support']})" for c in H.CLASSES)
      + f". Settled macro-F1 {mo['settled']['macro_f1']:.3f} (every settled window correct). Deployed model: macro-F1 {md['all']['macro_f1']:.3f} (all) / {md['settled']['macro_f1']:.3f} (settled); "
        f"its hold-out predictions agree with a freshly retrained HCRL+simulator RF on {100 * F['deployed_vs_retrained_agreement']:.1f} % of windows, so the table is reproducible. "
        f"Attack recall is ~0.997 with attack precision 0.91-0.94: the same boundary-window effect as for the rules. The hold-out has only "
        + ", ".join(f"{k.split('_')[0]}: {v}" for k, v in F["heldout_intrusions_per_file"].items() if v) + " intrusions per capture (injections sit mostly in the first 75 % of each file).\n")
    A("**Method.** 10 profile-relative traffic features per 100 ms window (`TRAFFIC_FEATURE_NAMES`), `RandomForestClassifier(60 trees, depth 12, balanced)`, trained on the first 75 % of every capture "
      "(windows within 0.6 s of a label change excluded from training), tested on the last 25 %. Deployed = `server/models/cyber_rf.joblib` loaded read-only.\n")
    A("### Figure `" + fig("hcrl_rf_importance") + "`\n")
    imp = sorted(mo["importance"].items(), key=lambda kv: -kv[1])
    A("**Caption draft.** Gini feature importance of the RandomForest (HCRL-only and deployed). Unknown-ID features and the largest per-ID rate ratio carry most of the decision.\n")
    A("**Key numbers (HCRL-only).** " + ", ".join(f"{k} {v:.3f}" for k, v in imp[:6]) + f"; steering_ratio {mo['importance']['steering_ratio']:.3f}, steering_rate {mo['importance']['steering_rate']:.4f}. "
      f"Shortcut check: dropping both steering features gives macro-F1 {F['ablation_no_steering_features']['all']['macro_f1']:.3f} (all) / {F['ablation_no_steering_features']['settled']['macro_f1']:.3f} (settled), "
      "so the possible 'steering ID missing = file fingerprint' shortcut is not what the model relies on (the steering ID is absent from three captures).\n")
    A("**Method.** `feature_importances_` of each fitted forest, ordered by the HCRL-only model.\n")
    A("### Figure `" + fig("hcrl_rf_confusion") + "`\n")
    A("**Caption draft.** Row-normalised hold-out confusion matrices (all windows) for the HCRL-only and the deployed RF.\n")
    A("**Key numbers.** Equal for both models: see `paper/results/hcrl_rf.json` (`confusion_all`); essentially all errors are normal windows right after a burst predicted as an attack and the first windows of an attack predicted normal.\n")
    A("**Method.** As above.\n")

    # ------------------------------------------------------------------ Exp 4
    A("## Exp 4: cross-domain transfer (key contribution)\n")
    A("### Tables `paper/tables/hcrl_transfer_settled.tex`, `hcrl_transfer_all.tex` and figure `" + fig("hcrl_transfer") + "`\n")
    A("**Caption draft.** Macro-F1 of an RF trained on simulator data, HCRL data or both, tested on the real HCRL hold-out and on fresh simulator runs. A simulator that injects at the published rates "
      "('nominal') transfers poorly to the real bus; the same simulator with the injection rate and legitimate-traffic loss measured from HCRL ('measured') transfers almost perfectly.\n")
    rows = ["| trained on | HCRL hold-out | fresh sim (measured) | fresh sim (nominal) |", "|---|---|---|---|"]
    for k, lab in [("synth_nominal", "sim nominal"), ("synth_measured", "sim measured"), ("hcrl", "HCRL"), ("hcrl_synth_measured", "HCRL + sim measured")]:
        rows.append(f"| {lab} | " + " | ".join(f"{g(k, t, 'all'):.3f} / {g(k, t, 'settled'):.3f}" for t in ("hcrl_heldout", "fresh_measured", "fresh_nominal")) + " |")
    A("**Key numbers (macro-F1 all / settled, mean over " + str(len(T["seeds"])) + " simulator seeds).**\n\n" + "\n".join(rows) + "\n")
    A(f"The simulator-only RF without measured behaviour scores {nom_pc['macro_f1']:.2f} on HCRL (seed 0, all windows): DoS recall {nom_pc['dos']['recall']:.2f}, fuzzy recall {nom_pc['fuzzy']['recall']:.3f}, "
      f"spoofing recall {nom_pc['spoofing']['recall']:.2f}; it labels almost everything normal. Reason (median settled DoS-window features, HCRL / nominal sim / measured sim): "
      f"unknown-ID rate {fm['dos']['hcrl']['unknown_fps']:.0f} / {fm['dos']['nominal']['unknown_fps']:.0f} / {fm['dos']['measured']['unknown_fps']:.0f} frames/s, "
      f"total rate ratio {fm['dos']['hcrl']['total_ratio']:.2f} / {fm['dos']['nominal']['total_ratio']:.2f} / {fm['dos']['measured']['total_ratio']:.2f}, "
      f"bus load {fm['dos']['hcrl']['bus_load_pct']:.0f} / {fm['dos']['nominal']['bus_load_pct']:.0f} / {fm['dos']['measured']['bus_load_pct']:.0f} %. "
      "The nominal simulator floods the bus; the real captures show a thinned bus. Transfer is asymmetric: the measured-simulator RF scores "
      f"{g('synth_measured', 'fresh_nominal', 'settled'):.2f} on nominal-simulator data. The historical figure 0.29 quoted in `EVALUATION.md` came from an older feature version; "
      f"re-running now gives {g('synth_nominal', 'hcrl_heldout', 'all'):.2f}. HCRL-trained RFs reach 1.00 on fresh simulator runs (settled), i.e. the learned decision generalises to the simulator when it was fitted on real data.\n")
    A("**Method.** For each of 5 simulator seeds, `ml_training.generate_dataset.generate(seed)` is run twice with identical job lists and seeds, once with the stock profile (measured) and once with "
      "`dataclasses.replace(profile, attack_behaviour={})` patched into `common.can_profiles.CAN_PROFILES` inside the script (nominal; nothing under `common/` is edited), plus a fresh test set "
      "(3 normal + 2 runs of each of the 5 simulated attacks, seeds never used for training). RFs (`ml_training.train._rf`) are trained on the simulator train split (whole runs held out), on HCRL train windows, or both, "
      "and scored by macro-F1 over {normal, DoS, fuzzy, spoofing}.\n")

    # ------------------------------------------------------------------ Exp 5
    A("## Exp 5: threshold sensitivity\n")
    A("### Figure `" + fig("hcrl_sensitivity") + "`, `" + fig("hcrl_sensitivity_vs_threshold") + "` and table `paper/tables/hcrl_sensitivity.tex`\n")
    A("**Caption draft.** Detection rate versus false-positive rate on settled windows when one rule constant is swept (the others fixed at the deployed values); star = deployed value. "
      "The second figure plots the same sweep against the constant itself.\n")
    parts = []
    for p, sw in S.items():
        pts = sw["points"]
        dpt = [q for q in pts if q["value"] == sw["default"]][0]
        lo_ok = [q["value"] for q in pts if q["recall_any_settled"] >= 0.99 and q["fpr_settled"] == 0]
        parts.append(f"{p}: deployed {sw['default']} gives recall {100 * dpt['recall_any_settled']:.1f} %, FPR {100 * dpt['fpr_settled']:.2f} %, "
                     f"{100 * dpt['intrusion_detect_rate']:.1f} % of intrusions found, {dpt['false_alerts_per_hour']:.1f} false alerts/h; values with recall >= 99 % and FPR 0: "
                     f"{min(lo_ok):g} to {max(lo_ok):g}" if lo_ok else f"{p}: deployed {sw['default']}")
    A("**Key numbers.** " + "; ".join(parts) + ". Range tested: " + "; ".join(f"{p} {sw['points'][0]['value']:g}-{sw['points'][-1]['value']:g}" for p, sw in S.items())
      + ". SPOOF_RATIO: " + f"{100 * S['SPOOF_RATIO']['points'][1]['fpr_settled']:.2f} % FPR appears at {S['SPOOF_RATIO']['points'][1]['value']:g} and is 0 from 1.2 upward (normal traffic stays below about 1.2x), "
        f"recall decays to {100 * S['SPOOF_RATIO']['points'][-1]['recall_any_settled']:.1f} % at {S['SPOOF_RATIO']['points'][-1]['value']:g}. "
        "The FPR is exactly 0 in the DoS and fuzzy sweeps over the whole range because normal traffic contains no unknown ID at all, so the curves are vertical lines; "
        "the real trade-off is only on the missed-detection side (an attacker slower than the threshold), not on false alarms. This is a property of the clean HCRL bus, not proof that the thresholds are robust on other cars. "
        "Fuzzy detection is insensitive from 2 to 30 distinct IDs because fuzzing produces ~100 distinct IDs per window.\n")
    A("**Method.** `server.app.analytics.SPOOF_RATIO / DOS_UNKNOWN_ID_FPS / FUZZY_MIN_IDS` are patched in worker processes, and the full rule engine is replayed over all five captures (no subsampling) for each value. "
      "Recall = fraction of attack windows of the targeted captures predicted as any attack (and as the right class, second curve); FPR = fraction of normal windows (all five captures, settled) predicted as an attack. "
      "Runtime about 4 min on 8 cores.\n")

    # ------------------------------------------------------------------ Exp 6
    A("## Exp 6: window size\n")
    A("### Table `paper/tables/hcrl_window.tex` and figure `" + fig("hcrl_window") + "`\n")
    A("**Caption draft.** Batch window versus detection latency and accuracy of the rule engine on real HCRL data. Latency grows roughly linearly with the window and is bounded below by it; "
      "detection stays complete.\n")
    A("**Key numbers.** " + "; ".join(
        f"{s} ms: {100 * W[str(s)]['detect_rate']:.1f} % detected, latency median/p95/max {W[str(s)]['latency_median_ms']:.0f}/{W[str(s)]['latency_p95_ms']:.0f}/{W[str(s)]['latency_max_ms']:.0f} ms, "
        f"{W[str(s)]['false_alerts_outside']} false alerts, macro-F1 {W[str(s)]['macro_f1_all']:.3f} (all) / {W[str(s)]['macro_f1_settled']:.3f} (settled)" for s in (50, 100, 200, 500)) + ". "
      "Window-level F1 is not comparable across sizes (a window is 'attack' if it holds any injected frame, so larger windows label more normal time as attack and the unsettled share changes); "
      "the settled F1 falls at 500 ms because a 500 ms window mixes both states.\n")
    A("**Method.** Windows are cut straight from the raw captures with `iter_windows(window_ms=...)` (profile-message frames kept, counts cover all frames) and replayed through the rules; "
      "the settle mask and the intrusion-merge gap scale with the window. Only the rules were run (not the RF).\n")

    # ------------------------------------------------------------------ Threats
    A("## Threats to validity\n")
    for t in [
        "**One car, one bus, one dataset.** Everything is the same Hyundai YF Sonata and the same recording sessions. Nothing here shows generalisation to other vehicles, other ID layouts or other bus loads.",
        "**Repetitive attacks.** Each capture is 300 near-identical bursts (about 3-5 s on, 3 s off), so 300 intrusions are far fewer than 300 independent samples and the 95 % Wilson intervals are optimistic. The HCRL attacks are also crude (floods and high-rate injection); a low-rate, replay, or in-rate spoof is not covered and the rate-based rules would not see it.",
        "**Labels.** A window is an attack window if it contains at least one injected frame; the ground truth is therefore tied to the window size and creates boundary 'errors'. The attack-free stretches inside attack captures are labelled normal. 'Settled' scores hide boundary effects and must not be quoted as operational accuracy.",
        "**Thresholds were tuned on this data.** `SPOOF_RATIO` and `DOS_UNKNOWN_ID_FPS` were changed after looking at the same captures (EVALUATION.md); the rule results are therefore in-sample for the thresholds. The time-contiguous RF hold-out does not remove this, and it is within the same sessions (no session-level split).",
        "**Small hold-out.** The last 25 % of each file holds only about 18-30 intrusions per attack class, and the injections concentrate in the first 75 %.",
        "**Normal-traffic baseline is short.** `normal_run_data.txt` is 506 s; per-hour false-alert rates are extrapolations, and zero observed false alerts is compatible with a non-zero true rate (the rule of three gives at most about 21/h at 95 % confidence from 506 s alone, plus the attack-free stretches).",
        "**Simulator is calibrated on the test domain.** The 'measured' simulator takes its injection rate and legitimate-traffic survival from the same HCRL captures used as the target, so the 0.32 to 0.96 gain demonstrates the value of calibrating on real data, not blind synthetic-to-real transfer. Four profile messages (0x386, 0x220, 0x4F1, 0x549) exist only in the simulator, and steering 0x2B0 is missing in three captures.",
        "**Fresh-simulator tests are in-family.** They share the generator with the simulator training data. Different seeds do not make them independent domains. The asymmetric nominal/measured transfer shows that RF scores depend on the generator assumptions.",
        "**Latency is a replay latency.** It is measured on capture timestamps with 100 ms batching and excludes the ESP32, the encrypted tunnel, network and server processing time; the first-alert definition ties it to the debounce logic.",
        "**Windows with timestamp discontinuities.** The captures concatenate sessions with gaps of hours; analysis is on windows with data, so the notion of 'duration' is active time, and detector state is carried across the jumps (no effect was observed).",
        "**Mechanical rules and health models are untested on real data** (no labelled faults; battery/brake/wheel/cluster messages are not on the HCRL bus). tunnel_attack is event-based and outside this evaluation.",
        "**Random seeds.** RFs use `random_state=0`; the simulator results are averaged over 5 seeds but the HCRL-only RF was trained once.",
    ]:
        A(f"- {t}")
